    rows = list(state.rows.get(arm) or [])
    if rows:
        return rows
    path = state.input_path(f"rows_{arm}_tag-{TAG}.jsonl")
    if path is not None:
        for index, line in enumerate(Path(path).read_text().splitlines(), start=1):
            line = line.strip()
            if not line:
